// Generated by AI (UnitTest MCP)
import { execFileSync, spawnSync } from "node:child_process";
import { cpSync, mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { afterAll, afterEach, beforeAll, describe, expect, it } from "vitest";

const publisher = join(
  dirname(fileURLToPath(import.meta.url)),
  "../../../scripts/canonical-push.mjs"
);
const temporaryDirectories = [];
const gitRepositoryVariables = [
  "GIT_DIR",
  "GIT_WORK_TREE",
  "GIT_COMMON_DIR",
  "GIT_INDEX_FILE",
  "GIT_OBJECT_DIRECTORY",
  "GIT_ALTERNATE_OBJECT_DIRECTORIES",
];

const isolatedGitEnvironment = (environment = process.env) => {
  const isolated = { ...environment };
  for (const variable of gitRepositoryVariables) {
    delete isolated[variable];
  }
  return isolated;
};

afterEach(() => {
  for (const directory of temporaryDirectories.splice(0)) {
    rmSync(directory, { recursive: true, force: true });
  }
});

const git = (cwd, args) =>
  execFileSync("git", args, {
    cwd,
    encoding: "utf8",
    stdio: "pipe",
    env: isolatedGitEnvironment(),
  }).trim();

const commitFile = (repo, name, content, message) => {
  writeFileSync(join(repo, name), content);
  git(repo, ["add", "--", name]);
  git(repo, ["commit", "-m", message]);
};

const sandbox = () => {
  const root = mkdtempSync(join(tmpdir(), "mindleak-canonical-push-"));
  temporaryDirectories.push(root);
  cpSync(templateRoot, root, { recursive: true });
  return { root, remote: join(root, "remote.git"), repo: join(root, "repo") };
};

// Built once and copied, because seventeen tests rebuilding the same fixture
// cost ten git subprocesses each — measured at 4019ms per test against 238ms
// for a single bare git spawn, so most of a test's budget went on scaffolding
// rather than on the publisher under test. Copying costs about 500ms.
let templateRoot;

beforeAll(() => {
  templateRoot = mkdtempSync(join(tmpdir(), "mindleak-canonical-push-template-"));
  const remote = join(templateRoot, "remote.git");
  const repo = join(templateRoot, "repo");
  mkdirSync(repo);
  git(templateRoot, ["init", "--bare", remote]);
  git(repo, ["init", "-b", "main"]);
  git(repo, ["config", "user.name", "Canonical Push Test"]);
  git(repo, ["config", "user.email", "canonical-push@example.invalid"]);
  commitFile(repo, "README.md", "initial\n", "initial");
  // Relative, so a copied sandbox pushes to ITS OWN remote with no fixup. An
  // absolute path would survive the copy and quietly aim every test at the
  // template's remote, letting one test observe another's pushes.
  git(repo, ["remote", "add", "origin", "../remote.git"]);
  git(repo, ["push", "-u", "origin", "main"]);
});

afterAll(() => {
  if (templateRoot) rmSync(templateRoot, { recursive: true, force: true });
});

const runPublisher = (repo, args = [], env = process.env) =>
  spawnSync(process.execPath, [publisher, ...args], {
    cwd: repo,
    encoding: "utf8",
    env: isolatedGitEnvironment(env),
  });

// Derived, not guessed. Each test spawns the real publisher, which spawns git
// many times; the slowest measures 12.75s on an idle machine after the shared
// fixture landed. CI ran roughly four times slower when this suite timed out,
// which puts the worst case near 50s, so 30s was never enough margin and the
// failure landed on whichever test was unlucky rather than on a slow one.
const TIMEOUT_MS = 60_000;

const SESSION = "0123456789abcdef0123456789abcdef";
const AGENT = "session:v1:0123456789abcdef0123456789abcdef";

/**
 * A stub ledger speaking the server's newline-delimited JSON-RPC.
 *
 * Publication now requires a live claim (ADR-0049), so a sandbox with no ledger
 * could only ever assert refusal. Standing one up keeps the publish path itself
 * under test rather than trading that coverage away for the new guard.
 */
const stubLedger = (root, { claims = [], overlaps = [] } = {}) => {
  const path = join(root, "stub-ledger.mjs");
  const source = [
    'import { createInterface } from "node:readline";',
    `const board = ${JSON.stringify(claims)};`,
    `const overlaps = ${JSON.stringify(overlaps)};`,
    "const reply = (id, value) =>",
    "  process.stdout.write(",
    "    JSON.stringify({",
    '      jsonrpc: "2.0",',
    "      id,",
    '      result: { content: [{ type: "text", text: JSON.stringify(value) }] },',
    '    }) + "\\n",',
    "  );",
    'createInterface({ input: process.stdin }).on("line", (line) => {',
    "  if (!line.trim()) return;",
    "  const message = JSON.parse(line);",
    '  if (message.method === "initialize") return;',
    "  const name = message.params?.name;",
    "  const view = message.params?.arguments?.view;",
    `  if (name === "open_session") reply(message.id, { agent_id: ${JSON.stringify(AGENT)} });`,
    '  else if (name === "ingest_commit") reply(message.id, { node_ids: ["intent:test"] });',
    // The task cluster collapsed to one verb per stage, so the board and the
    // overlap report are views of `task_query` rather than tools of their own.
    // A stub answering only the retired names leaves every call unanswered, and
    // canonical-push then reports "the Lodestar ledger is unreachable" — true
    // about this stub, and a lie about the change under test.
    '  else if (name === "task_query" && view === "overlap") reply(message.id, { claims: overlaps });',
    '  else if (name === "task_query") reply(message.id, board);',
    "});",
    "",
  ].join("\n");
  writeFileSync(path, source);
  return path;
};

const claimEnv = (root, options) => {
  const server = stubLedger(root, options);
  return {
    ...process.env,
    LODESTAR_SESSION_ID: SESSION,
    LODESTAR_MCP_BIN: server,
    MINDLEAK_MCP_BIN: server,
  };
};

const liveClaim = {
  id: "task:live",
  status: "claimed",
  owner: AGENT,
  lease_expires_at: Math.floor(Date.now() / 1000) + 3600,
};

describe("canonical-push", () => {
  // The fixture is now shared, so this is the property that makes sharing safe:
  // a copied sandbox must push to its own remote. An absolute origin URL would
  // survive the copy and silently aim every test at the template's remote,
  // where one test would see another's refs and the failures would look random.
  it(
    "gives each sandbox its own remote",
    () => {
      const first = sandbox();
      const second = sandbox();
      git(first.repo, ["checkout", "-b", "fleet/first"]);
      commitFile(first.repo, "first.txt", "first\n", "first only");
      git(first.repo, ["push", "origin", "fleet/first"]);

      const landed = git(first.root, [
        "--git-dir",
        first.remote,
        "rev-parse",
        "refs/heads/fleet/first",
      ]);
      expect(landed).toBe(git(first.repo, ["rev-parse", "HEAD"]));
      expect(() =>
        git(second.root, ["--git-dir", second.remote, "rev-parse", "refs/heads/fleet/first"])
      ).toThrow();
    },
    TIMEOUT_MS
  );

  it("provides both MCP planes for claimed publication", () => {
    const { root } = sandbox();
    const environment = claimEnv(root, { claims: [liveClaim] });

    expect(environment.MINDLEAK_MCP_BIN).toBe(environment.LODESTAR_MCP_BIN);
  });

  it(
    "refuses direct publication from main",
    () => {
      const { repo } = sandbox();

      const result = runPublisher(repo);

      expect(result.status).toBe(2);
      expect(result.stderr).toMatch(/direct protected-branch publication is forbidden/);
    },
    TIMEOUT_MS
  );

  it(
    "refuses publication while the worktree has staged changes",
    () => {
      const { repo } = sandbox();
      git(repo, ["checkout", "-b", "fleet/staged"]);
      writeFileSync(join(repo, "staged.txt"), "not committed\n");
      git(repo, ["add", "--", "staged.txt"]);

      const result = runPublisher(repo);

      expect(result.status).toBe(2);
      expect(result.stderr).toMatch(/worktree has uncommitted changes/);
    },
    TIMEOUT_MS
  );

  it(
    "refuses publication while the worktree has unstaged or untracked changes",
    () => {
      const { repo } = sandbox();
      git(repo, ["checkout", "-b", "fleet/dirty"]);
      writeFileSync(join(repo, "README.md"), "modified\n");
      writeFileSync(join(repo, "untracked.txt"), "untracked\n");

      const result = runPublisher(repo);

      expect(result.status).toBe(2);
      expect(result.stderr).toMatch(/worktree has uncommitted changes/);
    },
    TIMEOUT_MS
  );

  it(
    "refuses publication from a detached HEAD",
    () => {
      const { repo } = sandbox();
      git(repo, ["checkout", "--detach"]);

      const result = runPublisher(repo);

      expect(result.status).toBe(2);
      expect(result.stderr).toMatch(/HEAD is detached/);
    },
    TIMEOUT_MS
  );

  it(
    "allows the pre-push hook only through the canonical publisher",
    () => {
      const { repo } = sandbox();
      git(repo, ["checkout", "-b", "fleet/guarded"]);

      const direct = runPublisher(repo, ["--verify-pre-push"]);
      const canonical = runPublisher(repo, ["--verify-pre-push"], {
        ...process.env,
        MINDLEAK_CANONICAL_PUBLISH: "1",
      });

      expect(direct.status).toBe(2);
      expect(direct.stderr).toMatch(/pushes must run through/);
      expect(canonical.status, canonical.stderr).toBe(0);
    },
    TIMEOUT_MS
  );

  /**
   * Publishing `vX.Y.Z` is the documented release step, and the branch guard
   * used to reject it three ways at once: `symbolic-ref` fails on a detached
   * HEAD, a tag has no claim, and the publisher flag is only set when this
   * script pushes a branch. Cutting a release therefore required an
   * undocumented environment variable. These assert the tag path on its own
   * terms rather than re-testing the branch path.
   *
   * `PRE_COMMIT_REMOTE_BRANCH` is how the destination arrives: pre-commit
   * consumes the pre-push stdin before the hook runs, so the refs cannot be
   * read from there.
   */
  it(
    "lets a release tag through the pre-push hook without the publisher flag",
    () => {
      const { repo } = sandbox();
      git(repo, ["tag", "-a", "v9.9.9", "-m", "release"]);

      const result = runPublisher(repo, ["--verify-pre-push"], {
        ...process.env,
        PRE_COMMIT_REMOTE_BRANCH: "refs/tags/v9.9.9",
        MINDLEAK_CANONICAL_PUBLISH: undefined,
      });

      expect(result.status, result.stderr).toBe(0);
      expect(result.stdout).toMatch(/v9\.9\.9 -> [0-9a-f]{7}, contained in origin\/main/);
    },
    TIMEOUT_MS
  );

  it(
    "refuses a release tag naming a commit that never landed on main",
    () => {
      const { repo } = sandbox();
      git(repo, ["checkout", "-b", "fleet/unmerged"]);
      commitFile(repo, "unmerged.txt", "not on main\n", "unmerged work");
      git(repo, ["tag", "-a", "v9.9.9", "-m", "premature release"]);

      const result = runPublisher(repo, ["--verify-pre-push"], {
        ...process.env,
        PRE_COMMIT_REMOTE_BRANCH: "refs/tags/v9.9.9",
      });

      expect(result.status).toBe(2);
      expect(result.stderr).toMatch(/not on origin\/main/);
      expect(result.stderr).toMatch(/must name a commit that has landed/);
    },
    TIMEOUT_MS
  );

  it(
    "still guards branch pushes when a tag ref is not what is being pushed",
    () => {
      const { repo } = sandbox();
      git(repo, ["checkout", "-b", "fleet/still-guarded"]);

      const result = runPublisher(repo, ["--verify-pre-push"], {
        ...process.env,
        PRE_COMMIT_REMOTE_BRANCH: "refs/heads/fleet/still-guarded",
        MINDLEAK_CANONICAL_PUBLISH: undefined,
      });

      expect(result.status).toBe(2);
      expect(result.stderr).toMatch(/pushes must run through/);
    },
    TIMEOUT_MS
  );

  it(
    "refuses publication when the remote branch is not an ancestor",
    () => {
      const { root, remote, repo } = sandbox();
      const peer = join(root, "peer");
      git(repo, ["checkout", "-b", "fleet/diverged"]);
      commitFile(repo, "base.txt", "base\n", "fleet base");
      git(repo, ["push", "-u", "origin", "fleet/diverged"]);

      git(root, ["clone", remote, peer]);
      git(peer, ["config", "user.name", "Peer"]);
      git(peer, ["config", "user.email", "peer@example.invalid"]);
      git(peer, ["checkout", "fleet/diverged"]);
      commitFile(peer, "remote.txt", "remote\n", "remote advance");
      git(peer, ["push", "origin", "fleet/diverged"]);

      commitFile(repo, "local.txt", "local\n", "local advance");
      const result = runPublisher(repo);

      expect(result.status).toBe(2);
      expect(result.stderr).toMatch(/is not an ancestor of HEAD/);
    },
    TIMEOUT_MS
  );

  it(
    "publishes the current fleet branch's exact HEAD",
    () => {
      const { root, remote, repo } = sandbox();
      git(repo, ["checkout", "-b", "fleet/canonical"]);
      commitFile(repo, "feature.txt", "feature\n", "fleet feature");
      const expected = git(repo, ["rev-parse", "HEAD"]);

      const result = runPublisher(repo, [], claimEnv(root, { claims: [liveClaim] }));

      expect(result.status, result.stderr).toBe(0);
      expect(result.stdout).toMatch(/published HEAD -> origin\/fleet\/canonical/);
      expect(git(root, ["--git-dir", remote, "rev-parse", "refs/heads/fleet/canonical"])).toBe(
        expected
      );
    },
    TIMEOUT_MS
  );

  it(
    "reports newly added unbound source files after publication",
    () => {
      const { root, repo } = sandbox();
      const marker = join(root, "binding-observer-ran.txt");
      mkdirSync(join(repo, "scripts"));
      writeFileSync(
        join(repo, "scripts", "binding-audit.mjs"),
        [
          'import { writeFileSync } from "node:fs";',
          'const expected = ["--new-since", "origin/main"];',
          "if (JSON.stringify(process.argv.slice(2)) !== JSON.stringify(expected)) process.exit(2);",
          'writeFileSync(process.env.BINDING_OBSERVER_MARKER, "observed\\n");',
          "",
        ].join("\n")
      );
      git(repo, ["checkout", "-b", "fleet/binding-observer"]);
      git(repo, ["add", "--", "scripts/binding-audit.mjs"]);
      git(repo, ["commit", "-m", "add binding observer fixture"]);

      const result = runPublisher(repo, [], {
        ...claimEnv(root, { claims: [liveClaim] }),
        BINDING_OBSERVER_MARKER: marker,
      });

      expect(result.status, result.stderr).toBe(0);
      expect(git(repo, ["status", "--porcelain"])).toBe("");
      expect(readFileSync(marker, "utf8")).toBe("observed\n");
    },
    TIMEOUT_MS
  );

  it(
    "reports the binding audit failure without blocking publication",
    () => {
      const { root, repo } = sandbox();
      mkdirSync(join(repo, "scripts"));
      writeFileSync(
        join(repo, "scripts", "binding-audit.mjs"),
        [
          'console.error("binding-audit: legacy schema needs migration");',
          "process.exit(2);",
          "",
        ].join("\n")
      );
      git(repo, ["checkout", "-b", "fleet/binding-audit-failure"]);
      git(repo, ["add", "--", "scripts/binding-audit.mjs"]);
      git(repo, ["commit", "-m", "add failing binding audit fixture"]);

      const result = runPublisher(repo, [], claimEnv(root, { claims: [liveClaim] }));

      expect(result.status, result.stderr).toBe(0);
      expect(result.stderr).toMatch(
        /binding audit failed but remains non-fatal: binding-audit: legacy schema needs migration/
      );
    },
    TIMEOUT_MS
  );

  // ADR-0049: the ledger stops being optional at exactly this boundary.
  it(
    "refuses publication with no live claim",
    () => {
      const { root, repo } = sandbox();
      git(repo, ["checkout", "-b", "fleet/unclaimed"]);
      commitFile(repo, "feature.txt", "feature\n", "unclaimed feature");

      const result = runPublisher(repo, [], claimEnv(root, { claims: [] }));

      expect(result.status).toBe(2);
      expect(result.stderr).toMatch(/no live Lodestar claim/);
      expect(result.stderr).toMatch(/task_claim/);
    },
    TIMEOUT_MS
  );

  // An unreachable ledger must not become the way past the gate, unlike the
  // auto-merge guard, where an absent `gh` is an ordinary condition.
  it(
    "refuses publication when the ledger cannot be reached",
    () => {
      const { root, repo } = sandbox();
      git(repo, ["checkout", "-b", "fleet/no-ledger"]);
      commitFile(repo, "feature.txt", "feature\n", "feature");

      const result = runPublisher(repo, [], {
        ...process.env,
        LODESTAR_SESSION_ID: SESSION,
        LODESTAR_MCP_BIN: join(root, "absent-ledger.mjs"),
      });

      expect(result.status).toBe(2);
      expect(result.stderr).toMatch(/unreachable/);
    },
    TIMEOUT_MS
  );

  // Advisory, never a gate: the collision is named and the push still lands.
  it(
    "reports an overlapping claim but publishes anyway",
    () => {
      const { root, repo } = sandbox();
      git(repo, ["checkout", "-b", "fleet/overlapping"]);
      commitFile(repo, "feature.txt", "feature\n", "feature");

      const result = runPublisher(
        repo,
        [],
        claimEnv(root, {
          claims: [liveClaim],
          overlaps: [{ task_id: "task:theirs", owner: "agent-b", matching_paths: ["feature.txt"] }],
        })
      );

      expect(result.status, result.stderr).toBe(0);
      expect(result.stderr).toMatch(/agent-b/);
      expect(result.stdout).toMatch(/published HEAD/);
    },
    TIMEOUT_MS
  );

  it(
    "publishes a linked worktree branch's exact HEAD",
    () => {
      const { root, remote, repo } = sandbox();
      const linked = join(root, "linked");
      git(repo, ["worktree", "add", "-b", "fleet/linked", linked]);
      commitFile(linked, "feature.txt", "linked feature\n", "linked feature");
      const expected = git(linked, ["rev-parse", "HEAD"]);

      const result = runPublisher(linked, [], claimEnv(root, { claims: [liveClaim] }));

      expect(result.status, result.stderr).toBe(0);
      expect(result.stdout).toMatch(/published HEAD -> origin\/fleet\/linked/);
      expect(git(root, ["--git-dir", remote, "rev-parse", "refs/heads/fleet/linked"])).toBe(
        expected
      );
    },
    TIMEOUT_MS
  );
});
